import java.util.*;

class Solution {
    public int largestPerimeter(int[] sticks) {
        int[] a = sticks.clone();
        Arrays.sort(a);
        // Try the longest side first; its best partners are the next two
        for (int i = a.length - 1; i >= 2; i--) {
            if (a[i - 2] + a[i - 1] > a[i]) return a[i - 2] + a[i - 1] + a[i];
        }
        return 0;
    }
}

