function largestPerimeter(sticks) {
  const a = [...sticks].sort((p, q) => p - q);
  for (let i = a.length - 1; i >= 2; i--) if (a[i - 2] + a[i - 1] > a[i]) return a[i - 2] + a[i - 1] + a[i];
  return 0;
}
